// Macht aus der Antwort eine Zeile je Event, das angelegt wuerde. Gedacht
// zum Durchsehen, bevor der taegliche Lauf zum ersten Mal scharf geschaltet
// wird — und danach immer dann, wenn eine Quelle sich geaendert haben koennte.

const r = $input.first().json;

if (r.error) {
  throw new Error(`${r.error}${r.detail ? ` — ${r.detail}` : ''}${r.hint ? ` (${r.hint})` : ''}`);
}

const zeilen = [];

for (const s of r.sources ?? []) {
  if (s.error) {
    zeilen.push({ json: { quelle: s.source, art: 'FEHLER', text: s.error } });
    continue;
  }
  for (const i of s.wouldInsert ?? []) {
    zeilen.push({
      json: { quelle: s.source, art: 'neu', datum: i.date, titel: i.title, slug: i.slug, ort: i.venue },
    });
  }
  for (const u of s.wouldUpdate ?? []) {
    zeilen.push({
      json: { quelle: s.source, art: 'geaendert', slug: u.slug, aenderungen: u.changes },
    });
  }
  for (const n of s.notes ?? []) {
    zeilen.push({ json: { quelle: s.source, art: 'Hinweis', text: n } });
  }
}

if (zeilen.length === 0) {
  return [{ json: { ergebnis: 'Nichts zu tun — alle Quellen sind aktuell abgebildet.' } }];
}

return zeilen;
